let ctx = flow.get('bathroom_ctx');
const STALE_MS = 2 * 60 * 60 * 1000; // 2h - if the brain hasn't run this recently, don't trust old session state
if (!ctx || !ctx.updated || (Date.now() - ctx.updated) > STALE_MS) {
    ctx = { state: 'idle', presence: 'off', entry_hum: null, peak_hum: null, updated: 0 };
