if (typeof ctx.presence !== 'string') ctx.presence = (msg.presence === 'on') ? 'on' : 'off';
ctx.updated = Date.now();

// States: idle (fan off) -> occupied (presence, fan on) -> toilet (presence left, timer
// armed) -> idle, OR idle/toilet -> shower (humidity/rate spike, fan on) -> idle.
// `ctx.state` is the single source of truth; everything else (fan, timers, dashboard
// sync) is derived from state transitions below.

const t       = msg.trigger_type;
const pwr     = flow.get('power_available') !== false; // true unless explicitly false
const heating = flow.get('heating_active') || false;

const prev_state = ctx.state;
const prev_peak  = ctx.peak_hum;

const ARM    = { payload: 'arm' };
const CANCEL = { reset: 'cancel' };

let o2 = null, o3 = null, o4 = null, o5 = null, o6 = null, o7 = null, o8 = null, o9 = null;
let sync_trigger = t;
let sync_hum = NaN, sync_rate = NaN;
let fan_target = null; // 'on' | 'off' | null - decided by state transitions below

const reason = (trig, h, r, ctx, pwr) => {
    const fh  = isNaN(h) ? '' : ` hum=${h}%`;
    const fr  = isNaN(r) ? '' : ` rate=${r.toFixed(2)}%/min`;
    const fpw = pwr ? '' : ' [light off]';
    switch (trig) {
        case 'r-detect':     return `R-detect${fr}${fh}${fpw}`;
        case 'rule2':        return `Hum rise +${(h-ctx.entry_hum).toFixed(1)}%${fh}${fpw}`;
        case 'rule2b':       return `Abs. ceiling${fh} (entry=${ctx.entry_hum}%)${fpw}`;
        case 'presence':     return `Presence: entered${fpw}`;
        case 'pir_settled':  return `PIR settled: toilet pre-arm${fpw}`;
        case 'toilet_fired': return `Toilet: 5-min${fpw}`;
        case 'rclear_fired': return `R-clear: 3-min confirmed${fpw}`;
        case 'rule4':        return `Rule 4: cleared to${fh}${fpw}`;
        case 'heating_fired':return `HVAC cutoff: 20-min${fpw}`;
        case 'safety_fired': return `Safety: 75-min${fpw}`;
        case 'watchdog':     return pwr ? 'Watchdog' : 'Watchdog [light off - queued for power-up]';
        default:             return trig + fpw;
    }
};

if (t === 'presence') {
    const pres = msg.presence;
    if (pres !== 'on' && pres !== 'off') { flow.set('bathroom_ctx', ctx); return [null,null,null,null,null,null,null,null,null]; }
    ctx.presence = pres;
