    if (pres === 'on') {
        const h = parseFloat(msg.bathroom_hum);
        if (!isNaN(h)) { ctx.entry_hum = h; ctx.peak_hum = h; }
        ctx.state = 'occupied';
        o2 = CANCEL; o3 = CANCEL; o4 = CANCEL; o6 = CANCEL;
        fan_target = 'on';
        sync_trigger = 'presence';
