        {
            const tod = global.get('TimeOfDay.LastChange') || '';
            const preEarly = ['very-early-morning','civilDawn','nauticalDawn',
                              'nightEnd','2HoursPriorNightEnd'];
            const aestH = (new Date().getUTCHours() + 10) % 24;
