            ctx.entry_hum = h; ctx.peak_hum = h;
            o2 = CANCEL; o3 = CANCEL; o4 = CANCEL; o6 = CANCEL;
            sync_trigger = 'rule4';
            fan_target = 'off';
        }
    }

