    const h    = parseFloat(msg.bathroom_hum);
    if (isNaN(rate)) { flow.set('bathroom_ctx', ctx); return [null,null,null,null,null,null,null,null,null]; }
    sync_hum = h; sync_rate = rate;

    if (!isNaN(h)) {
        if (ctx.entry_hum === null) { ctx.entry_hum = h; ctx.peak_hum = h; }
        if (h > ctx.peak_hum) ctx.peak_hum = h;
    }

    if (ctx.state !== 'shower' && rate >= 0.02) {
        const was_idle = ctx.state === 'idle';
        ctx.state = 'shower';
        o2 = CANCEL;
        sync_trigger = 'r-detect';
        {
            const tod = global.get('TimeOfDay.LastChange') || '';
            const preEarly = ['very-early-morning','civilDawn','nauticalDawn',
