            o6 = CANCEL;
        } else if (ctx.presence === 'off' && rate <= -0.005 && !isNaN(h) && ctx.peak_hum - h >= 2) {
            o6 = ARM;
        }
    }

} else if (t === 'toilet_fired') {
    if (ctx.state === 'toilet') {
        ctx.state = 'idle';
        fan_target = 'off';
    }

} else if (t === 'rclear_fired') {
    if (ctx.state === 'shower' && ctx.presence === 'off') {
