flow.set('bathroom_ctx', ctx);

// o1 - Fan control. ON is sent unconditionally; OFF is gated on power (the watchdog
// resync above will retry once power returns).
let o1 = null;
if (fan_target === 'on') {
    o1 = { payload: 'on' };
} else if (fan_target === 'off' && pwr) {
    o1 = { payload: 'off' };
}

// o7 - HA helper state sync (drives input_select.bathroom_mode + dashboard text)
const peak_changed = ctx.state === 'shower' && ctx.peak_hum !== prev_peak;
if (o1 !== null || state_changed || peak_changed) {
    o7 = {payload: {
        mode: ctx.state,
        fan_on: fan_target === 'on', fan_off: fan_target === 'off',
        mode_changed: state_changed, peak_changed,
        reason: reason(sync_trigger, sync_hum, sync_rate, ctx, pwr),
        entry_hum: ctx.entry_hum,
        peak_hum: ctx.peak_hum,
    }};
}

// o8 - HA timer countdown sync
if      (o4 && o4.payload === 'arm') o8 = {payload: {action: 'start', duration: 1200}}; // heating cutoff, 20min
else if (o3 && o3.payload === 'arm') o8 = {payload: {action: 'start', duration: 4500}}; // safety cutoff, 75min
else if (o2 && o2.payload === 'arm') o8 = {payload: {action: 'start', duration: 300}};  // toilet, 5min
else if (o6 && o6.payload === 'arm') o8 = {payload: {action: 'start', duration: 180}};  // r-clear, 3min
