return (next !== prev) ? {payload: next} : null;

const p = msg.payload;

// O1: mode (idle/occupied/toilet/shower) -> input_select, on mode change
const o1 = p.mode_changed ? {payload: p.mode} : null;

// O2: fan_on_reason text (fan-on events only)
const o2 = (p.fan_on && p.reason) ? {payload: p.reason} : null;

// O3: fan_off_reason text (fan-off events only)
const o3 = (p.fan_off && p.reason) ? {payload: p.reason} : null;

// O4: entry_hum — set when fan turns on (new session baseline)
