// This avoids the hardcoded LAST_KNOWN_SUM problem
const haUrl = global.get('homeassistant.homeAssistant.baseUrl') || 'http://supervisor/core';
const token = global.get('homeassistant.homeAssistant.access_token');

const end = new Date();
const start = new Date(end.getTime() - 48 * 3600 * 1000);

msg.haStatsRequest = {
