        period: 'hour',
        types: ['sum'],
        start_time: start.toISOString(),
        end_time: end.toISOString()
    })
};

msg.url = msg.haStatsRequest.url;
msg.method = 'POST';
msg.headers = msg.haStatsRequest.headers;
msg.payload = msg.haStatsRequest.body;

return msg;

// ── 1. Extract last known sum from LTS response ──
let lastSum = 734.5; // fallback if LTS is empty
try {
    const ltsData = msg.payload;
    const entries = ltsData['sensor.water_usage_mains'] || [];
    if (entries.length > 0) {
        lastSum = entries[entries.length - 1].sum || lastSum;
    }
    node.warn('Last LTS sum: ' + lastSum + 'L (' + entries.length + ' entries found)');
} catch(e) {
    node.warn('Could not read LTS sum, using fallback: ' + lastSum);
}

// ── 2. Get the SEW data saved earlier ──
const raw = msg._sewData;

// Adapt field names to match SEW API response
// Check debug_raw_sew output to confirm actual field names
const readings = raw.readings || raw.usageData || raw.data || raw.usage;
const dateStr = raw.apiDate || raw.date || raw.targetDate || raw.dateFor;

if (!readings || !readings.length) {
    node.error('No readings in SEW payload. Check debug_raw_sew for actual structure: ' + JSON.stringify(Object.keys(raw)));
    return null;
}

if (!dateStr) {
    node.error('No date in SEW payload. Keys available: ' + JSON.stringify(Object.keys(raw)));
    return null;
}

// ── 3. Get DST-aware Melbourne UTC offset for the target date ──
// Handles AEDT (UTC+11, Oct–Apr) and AEST (UTC+10, Apr–Oct) automatically
function getMelbourneOffsetHours(dateStr) {
    try {
        const tzStr = new Intl.DateTimeFormat('en-AU', {
            timeZone: 'Australia/Melbourne',
            timeZoneName: 'shortOffset'
        }).formatToParts(new Date(dateStr + 'T12:00:00Z'))
            .find(p => p.type === 'timeZoneName').value;
        // tzStr is like 'GMT+11' or 'GMT+10'
        return parseInt(tzStr.replace('GMT', ''), 10);
    } catch(e) {
        node.warn('DST offset lookup failed, defaulting to +11 (AEDT)');
        return 11;
    }
}

const melbOffset = getMelbourneOffsetHours(dateStr);
node.warn('Melbourne UTC offset for ' + dateStr + ': UTC+' + melbOffset);

// ── 4. Build the statistics array ──
// SEW hour[0] = midnight Melbourne = UTC midnight minus offset
// e.g. hour[0] at AEDT: Melbourne midnight = 13:00 previous day UTC
const statistics = [];
let runningSum = lastSum;

readings.forEach((litres, idx) => {
    const usage = parseFloat(litres) || 0;
    runningSum = Math.round((runningSum + usage) * 10) / 10;

    // Melbourne midnight in UTC: subtract offset hours, then add idx hours
    const utcMs = new Date(dateStr + 'T00:00:00Z').getTime()
                  - (melbOffset * 3600 * 1000)
                  + (idx * 3600 * 1000);
    const startISO = new Date(utcMs).toISOString();

    statistics.push({
        start: startISO,
        state: usage,
        sum: runningSum
    });
});

node.warn('Built ' + statistics.length + ' stats for ' + dateStr +
    ', sum: ' + lastSum + ' → ' + runningSum + 'L, first slot: ' + statistics[0].start);

// ── 5. Assemble final payload for recorder/import_statistics ──
msg.payload = {
    metadata: {
        has_mean: false,
        has_sum: true,
        name: null,
        source: 'recorder',
        statistic_id: 'sensor.water_usage_mains',
        unit_of_measurement: 'L'
    },
    stats: statistics   // websocket protocol uses 'stats' not 'statistics'
};

return msg;

