// Recast if EITHER:
//  (a) the target media_content_id differs from what the hub is
//      currently showing, OR
//  (b) more than FRESHNESS_MS has passed since the last successful
//      cast, even if the config hasn't changed.
//
// Why (b): a Nest Hub can silently drop to its ambient screensaver
// while the Cast session stays technically "connected" underneath.
// A pure media_content_id equality check can't detect that the
// screen itself has gone dark, so we periodically force a recast to
// wake it back up. Tune FRESHNESS_MS to taste - shorter recasts more
// often (more reliable, slightly more mute/unmute blips), longer
// waits longer before recovering from a screensaver timeout.
const FRESHNESS_MS = 10 * 60 * 1000; // 10 minutes

const last = flow.get('nesthub_last_cast') || {};
const currentId = msg.data && msg.data.attributes ? msg.data.attributes.media_content_id : undefined;
const targetId = msg.screen_config && msg.screen_config.media_content_id;

const sameConfig = currentId === targetId;
const isStale = !last.ts || (Date.now() - last.ts) > FRESHNESS_MS;

if (!sameConfig || isStale) {
    return [msg, null];
}
return [null, msg];

flow.set('nesthub_last_cast', {
    media_content_id: msg.screen_config && msg.screen_config.media_content_id,
    ts: Date.now()
});
return null;

// Hub was just turned off after 60 min idle - clear the tracked
// cast so the very next cast is never skipped on a stale timestamp.
flow.set('nesthub_last_cast', null);
return null;

// 1. Get the persistent history from file storage
const roomDb = flow.get("room_cleaning_history", "file") || {};
const segments = msg.segments || [];
const now = Date.now();

let maxDaysAgo = 0;

// 2. Find the oldest segment in the requested group
segments.forEach(segId => {
    let historyEntry = roomDb[segId];
    if (historyEntry && historyEntry.epoch) {
        let diffDays = (now - historyEntry.epoch) / 86400000;
        if (diffDays > maxDaysAgo) maxDaysAgo = diffDays;
    } else {
        // If no history exists for a segment, treat as brand new (high priority)
        maxDaysAgo = 99;
    }
});

// 3. Compare against your config thresholds
maxDaysAgo = Math.floor(maxDaysAgo);
msg.actual_days_since = maxDaysAgo;

// Output 1: initialise
if (maxDaysAgo >= 90) {
    msg.priority = "initialise";
    msg.start_now = true;
    node.status({ fill: "yellow", shape: "dot", text: "Initialise: " + msg.actual_days_since + "d" });
    return [msg, null, null, null];
}

// Output 1: Immediate/Critical
if (maxDaysAgo >= msg.max_days || maxDaysAgo >= 90) {
    msg.priority = (maxDaysAgo >= 90) ? "initialise" : "critical";
    msg.start_now = true;
    node.status({ fill: "red", shape: "dot", text: "Critical: " + msg.actual_days_since + "d" });
    return [null, msg, null, null];
}

// Output 2: Routine/Queue
if (maxDaysAgo >= msg.min_days) {
    msg.priority = "routine";
    msg.start_now = false;
    node.status({ fill: "yellow", shape: "dot", text: "Routine: " + msg.actual_days_since + "d" });
    return [null, null, msg, null];
}

