    });
}


// 2.1. Sort: Wet > Entries > Living > Carpet

const areaOrder = { "wet_area": 1, "entry_area": 2, "living_area": 3, "carpet_area": 4 };

const priorityOrder = { "manual": 0, "critical": 1, "routine": 2, "initialise": 1 };
// 2.2. Sort: Manual > Critical > Routine

queue.sort((a, b) => {
    let pA = priorityOrder[a.priority] ?? 5;
    let pB = priorityOrder[b.priority] ?? 5;

    // If priorities are different, sort by priority
    if (pA !== pB) return pA - pB;

    // If priorities are EQUAL, sort by area order
    let aA = areaOrder[a.topic] ?? 5;
    let aB = areaOrder[b.topic] ?? 5;
    return aA - aB;
});

// 3. Save once
flow.set("vacuum_queue", queue, "file");

// 4. Trigger logic
